    <script>(function(){const revealItems=document.querySelectorAll('.reveal-section');const show=item=>item.classList.add('is-visible');if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){show(entry.target);observer.unobserve(entry.target)}}),{threshold:.16,rootMargin:'0px 0px -8%'});revealItems.forEach(item=>observer.observe(item))}else{revealItems.forEach(show)}})();(function(){const overlay=document.querySelector('.opening-overlay');if(!overlay)return;const open=()=>overlay.classList.add('is-open');overlay.querySelector('.opening-open')?.addEventListener('click',open);overlay.querySelector('.opening-skip')?.addEventListener('click',open);overlay.querySelector('.opening-envelope')?.addEventListener('click',open);overlay.querySelector('.opening-envelope')?.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}})})();(function(){const countdown=document.querySelector('[data-wedding-countdown]');if(!countdown)return;const target=new Date(`${countdown.dataset.weddingCountdown}T00:00:00`).getTime();const update=()=>{const distance=Math.max(0,target-Date.now());const values={days:Math.floor(distance/86400000),hours:Math.floor(distance/3600000)%24,minutes:Math.floor(distance/60000)%60,seconds:Math.floor(distance/1000)%60};Object.entries(values).forEach(([key,value])=>{const element=countdown.querySelector(`[data-countdown="${key}"]`);if(element)element.textContent=String(value).padStart(2,'0')})};update();window.setInterval(update,1000)})();</script>
